@pytest.mark.parametrize("seed", [seeds.W1, seeds.MAX_E, seeds.MAX_I], ids=["W1", "MAX-E", "MAX-I"]) def test_R60_large_bills_fit_a_360_px_phone(open_app, seed): # qa.md at 360 x 780. The card is not displayed below 1024 px, so the figures are read on the strip and in the sheet. # Even rows carry no .wk (K2-11), so a MAX-E sheet holds none. A failure on a MAX bill is a design finding for the # owner, the CSS stays a byte copy (spec R60). page = open_app(seed=seed, viewport=VIEWPORTS[360]).page problems = [] overflow = page.evaluate("document.documentElement.scrollWidth - innerWidth") strip = page.evaluate(STRIP_TOTAL_JS) if overflow > 0 or strip is None or strip[0] > strip[1]: problems.append(f"before Splits the page overflows by {overflow} px and #stripTotal is {strip}") open_sheet(page) figures = page.evaluate(FIGURES_JS, "#splitsDlg .rbody") if figures["wide"] or not all(figures["found"][selector] for selector in (".r-amount", ".amt", ".r-lines dd")): problems.append(f"in the sheet {figures}") overflow = page.evaluate("document.documentElement.scrollWidth - innerWidth") if overflow > 0: problems.append(f"with the sheet open the page overflows by {overflow} px") > assert problems == [] E AssertionError: assert ['before Spli...s by 4124 px'] == [] E E Left contains 2 more items, first extra item: 'before Splits the page overflows by 4124 px and #stripTotal is [133, 133, True]' E Use -v to get more diff
